import ApiConstants from '../../../common/api_constants';
import RequestBase from '../../../common/request_base';
class InstallmentsRequest extends RequestBase {
    constructor(token, installmentsNumber, commerceCode = undefined, buyOrder = undefined) {
        super(`${ApiConstants.WEBPAY_ENDPOINT}/transactions/${token}/installments`, 'POST');
        this.installmentsNumber = installmentsNumber;
        this.commerceCode = commerceCode;
        this.buyOrder = buyOrder;
    }
    toJson() {
        return JSON.stringify({
            installments_number: this.installmentsNumber,
            commerce_code: this.commerceCode,
            buy_order: this.buyOrder
        });
    }
}
export { InstallmentsRequest };
